import { test, expect } from '@playwright/test';

test.describe('Keyboard Navigation - Tab Key', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/keyboard-navigation');
  });

  test('should navigate all interactive elements using Tab key', async ({ page }) => {
    // Verify initial state
    const firstButton = page.getByRole('button', { name: /first button/i });
    await expect(firstButton).toBeVisible();

    // Verify first button is focused
    await firstButton.click();
    await expect(firstButton).toBeFocused();

    // Verify tab key moves focus to next interactive element
    await page.keyboard.press('Tab');
    const secondButton = page.getByRole('button', { name: /second button/i });
    await expect(secondButton).toBeFocused();

    // Verify tab key moves focus to third interactive element
    await page.keyboard.press('Tab');
    const thirdButton = page.getByRole('button', { name: /third button/i });
    await expect(thirdButton).toBeFocused();

    // Verify tab key moves focus to form input
    await page.keyboard.press('Tab');
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeFocused();

    // Verify tab key moves focus to submit button
    await page.keyboard.press('Tab');
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeFocused();

    // Verify tab key wraps around to first interactive element
    await page.keyboard.press('Tab');
    await expect(firstButton).toBeFocused();
  });

  test('should handle tab navigation with disabled and non-interactive elements', async ({ page }) => {
    // Verify initial state
    const firstButton = page.getByRole('button', { name: /first button/i });
    await expect(firstButton).toBeVisible();

    // Verify first button is focused
    await firstButton.click();
    await expect(firstButton).toBeFocused();

    // Verify tab key moves focus to second button
    await page.keyboard.press('Tab');
    const secondButton = page.getByRole('button', { name: /second button/i });
    await expect(secondButton).toBeFocused();

    // Verify tab key skips disabled button
    await page.keyboard.press('Tab');
    const disabledButton = page.getByRole('button', { name: /disabled button/i });
    await expect(disabledButton).not.toBeFocused();

    // Verify tab key moves focus to third button
    await page.keyboard.press('Tab');
    const thirdButton = page.getByRole('button', { name: /third button/i });
    await expect(thirdButton).toBeFocused();

    // Verify tab key skips non-interactive element (e.button)
    await page.keyboard.press('Tab');
    const nonInteractiveElement = page.getByText(/non-interactive element/i);
    await expect(nonInteractiveElement).not.toBeFocused();

    // Verify tab key moves focus to form input
    await page.keyboard.press('Tab');
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeFocused();

    // Verify tab key wraps around to first button
    await page.keyboard.press('Tab');
    await expect(firstButton).toBeFocused();
  });
});
